mapper.select:
select notice_seq as noticeSeq, title, publish_yn as publishYn, pin_yn as pinYn, view_cnt as viewCnt, date(publish_dtm) as publishDate, date(mod_dtm) as updatedDate from bd_notice_mst where delete_flg = 'N'
and date(publish_dtm) >= #{startDate}
and date(publish_dtm) <= #{endDate}
order by pin_yn desc, publish_dtm desc, notice_seq desc limit #{size} offset #{offset}

select count(*)
from bd_notice_mst
where delete_flg = 'N'

  and date(publish_dtm) >= #{startDate}


  and date(publish_dtm) <= #{endDate}

select notice_file_seq as noticeFileSeq, notice_seq as noticeSeq, file_type as fileType, original_file_name as originalFileName, stored_file_name as storedFileName, stored_path as storedPath, content_type as contentType, file_size as fileSize, sort_ord as sortOrder, delete_flg as deleteFlg, reg_dtm as registeredAt, reg_id as registeredBy, mod_dtm as modifiedAt, mod_id as modifiedBy, null as fileUrl from bd_notice_file_dtl where notice_seq = #{noticeSeq} and delete_flg = 'N'
and file_type = #{fileType}
order by sort_ord asc, notice_file_seq asc

mapper.update:
update bd_notice_mst
set delete_flg = 'Y',
    mod_dtm = current_timestamp,
    mod_id = #{actorId}
where notice_seq = #{noticeSeq}
  and delete_flg = 'N'

update bd_notice_file_dtl
set delete_flg = 'Y',
    mod_dtm = current_timestamp,
    mod_id = #{actorId}
where notice_file_seq = #{noticeFileSeq}
  and delete_flg = 'N'

update bd_notice_file_dtl
set delete_flg = 'Y',
    mod_dtm = current_timestamp,
    mod_id = #{actorId}
where notice_seq = #{noticeSeq}
  and delete_flg = 'N'
